"""K-means clustering + NMI evaluation (Section 5.1 evaluation protocol)."""
import numpy as np
from sklearn.cluster import KMeans
from sklearn.metrics import normalized_mutual_info_score

from . import proximity_kernel as pk


def cluster_nmi(Z, y, n_clusters, seed, n_init=10):
    km = KMeans(n_clusters=n_clusters, init="k-means++", n_init=n_init, random_state=seed)
    labels = km.fit_predict(Z)
    return float(normalized_mutual_info_score(y, labels, average_method="arithmetic"))


def evaluate_seeds(Z, y, n_clusters, seeds, n_init=10):
    nmis = [cluster_nmi(Z, y, n_clusters, s, n_init=n_init) for s in seeds]
    return {
        "mean_nmi": float(np.mean(nmis)),
        "std_nmi": float(np.std(nmis)),
        "per_seed_nmi": [float(v) for v in nmis],
        "min_nmi": float(np.min(nmis)),
        "max_nmi": float(np.max(nmis)),
    }


def search_nbins(X, y, n_clusters, nbins_grid, seeds, mode="restricted", n_init=10):
    """R12: search nbins in the paper's grid; R11: average over repeated runs."""
    per_nbins = {}
    for nbins in nbins_grid:
        stats = {}
        Z, aux = pk.build_representation(X, nbins, mode=mode, stats=stats)
        res = evaluate_seeds(Z, y, n_clusters, seeds, n_init=n_init)
        res["diagnostics"] = stats
        per_nbins[str(nbins)] = res
    best_nbins = max(nbins_grid, key=lambda b: per_nbins[str(b)]["mean_nmi"])
    return {
        "best_nbins": int(best_nbins),
        "best_mean_nmi": per_nbins[str(best_nbins)]["mean_nmi"],
        "per_nbins": per_nbins,
        "nbins_grid": list(nbins_grid),
        "mode": mode,
    }
